const encoder=new TextEncoder();const decoder=new TextDecoder();
const base64=b=>{let s='';for(const x of new Uint8Array(b))s+=String.fromCharCode(x);return btoa(s);};
const bytes=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
export async function deriveKey(password,salt){const material=await crypto.subtle.importKey('raw',encoder.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:600000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
export async function newVault(password){if(password.length<12)throw new Error('Use at least 12 characters. A few random words work well.');const salt=crypto.getRandomValues(new Uint8Array(16));return {key:await deriveKey(password,salt),salt};}
export async function encryptVault(data,key,salt){const iv=crypto.getRandomValues(new Uint8Array(12));const ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,encoder.encode(JSON.stringify(data)));return {format:'long-mei-vault',version:1,kdf:'PBKDF2-SHA256',iterations:600000,salt:base64(salt),iv:base64(iv),ciphertext:base64(ciphertext)};}
export async function decryptVault(envelope,password){if(envelope?.format!=='long-mei-vault'||envelope.version!==1||envelope.kdf!=='PBKDF2-SHA256'||envelope.iterations!==600000||typeof envelope.ciphertext!=='string'||envelope.ciphertext.length>20e6)throw new Error('Unsupported or damaged backup.');const salt=bytes(envelope.salt),iv=bytes(envelope.iv);if(salt.length!==16||iv.length!==12)throw new Error('Damaged backup.');const key=await deriveKey(password,salt);try{const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,bytes(envelope.ciphertext));return {data:JSON.parse(decoder.decode(plain)),key,salt};}catch{throw new Error('Incorrect passphrase or damaged backup. Your saved data has not changed.');}}
